@startuml

class Customer {
  + Name : string
  + Surname : string
  + Age : int
  + Address : string
  + Profession : string
}

class Subscription {
  + Type : string
}

class Service {
  + Name : string
}

class WorkoutPlan {
  + Frequency : int
}

class Exercise {
  + Name : string
  + Repetitions : int
}

class MedicalStaff {
  + Name : string
}

class MedicalCheck {
  + Date : date
  + Weight : float
  + BodyFat : float
  + Electrocardiogram : string
  + RestingHeartbeat : int
  + StressHeartbeat : int
}

class FinancialRecord {
  + Month : int
  + Year : int
  + TotalIncome : double
}

Subscription "1" -- "*" Service : includes
Customer "1" -- "1" Subscription : has
Customer "1" -- "*" Service : requests
Customer "1" -- "0..1" WorkoutPlan : associatedWith
Customer "0..1" -- "0..*" MedicalCheck : undergoes
MedicalStaff "1" -- "*" MedicalCheck : performs
WorkoutPlan "1" *-- "*" Exercise : defines

@enduml

